create table if not exists agents(id uuid primary key,name varchar(120) not null,wallet_address varchar(80) not null unique,status varchar(20) not null default 'active',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists agent_policies(id uuid primary key,agent_id uuid not null references agents(id) on delete cascade,enabled boolean not null default true,network varchar(80) not null,allowed_merchants uuid[] not null default '{}',allowed_recipients text[] not null default '{}',allowed_assets text[] not null default '{}',max_per_payment numeric(78,0) not null,daily_budget numeric(78,0) not null,monthly_budget numeric(78,0) not null,approval_threshold numeric(78,0) not null,valid_from timestamptz not null,valid_until timestamptz not null,require_resource_binding boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists payment_approvals(id uuid primary key,payment_id varchar(128) not null references payments(payment_id),approver varchar(160) not null,decision varchar(16) not null check(decision in('approved','rejected')),reason varchar(500),created_at timestamptz not null default now());
create unique index if not exists one_approval_per_actor on payment_approvals(payment_id,approver);
insert into schema_migrations(version) values('002_agents_policies') on conflict do nothing;
